"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[48246],{48246:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/69bd99a2ba171008484405cee6dde1b2.jpg\\"\\n  title=\\"Good Measure\\"\\n  cuisine=\\"Cafe\\"\\n  address=\\"193 Lygon St, Carlton VIC 3053 Australia\\"\\n  rating=3.5\\n  tags=\\"cafe\\"\\n/>\\n</center>\\n\\n## Review\\nA cafe famous for its <mark>Mont Blanc Coffee</mark>.  \\nIt\'s a signature menu that went viral on social media — filter coffee topped with fresh cream, nutmeg, and orange zest, with a visually striking presentation.\\n\\nThe taste was honestly familiar, but I happened to be craving something sweet at the right moment, so it hit the spot.\\n\\nThe cafe was already full inside, so I was about to get takeout, but luckily an outdoor table opened up and I got to sit down and enjoy it properly.  \\nI also ordered a sandwich to make it a quick meal.\\n\\nThey operate as a cafe during the day and a cocktail bar in the evening.  \\nA great spot to drop by for a break if you\'re in the area.  \\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/69bd99a2ba171008484405cee6dde1b2.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Good Measure\\">\\n<img src=\\"/assets/snippets/location/50a5069a54ebf9fa6d6916d792958ba0.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Good Measure\\">\\n<img src=\\"/assets/snippets/location/709e1cdb9dcbfddd92d320326946003a.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Good Measure\\">\\n<img src=\\"/assets/snippets/location/20952e78871ee7632375042b09bc0f33.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Good Measure\\">\\n</pictures>\\n"}')}}]);